<template><div class="strategy-backdrop" @mousedown.self.stop="$emit('close')"><section ref="dialog" class="strategy-dialog" role="dialog" aria-modal="true" :aria-label="title" @keydown.stop="onKey" @keyup.stop><header><div><small>RIFTMON · CARNET STRATÉGIQUE</small><h2>{{ title }}</h2></div><button ref="close" aria-label="Fermer" @click="$emit('close')">×</button></header><main><slot/></main></section></div></template>
<script>
export default{props:{title:String},mounted(){this._previous=document.activeElement;this.$refs.close.focus({preventScroll:true});},beforeDestroy(){this._previous?.focus?.({preventScroll:true});},methods:{onKey(e){if(e.key==='Escape'){e.preventDefault();this.$emit('close');}if(e.key==='Tab')this.trap(e);},trap(e){const all=[...this.$refs.dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),summary')].filter(n=>n.getClientRects().length),first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}};
</script>
<style scoped>.strategy-backdrop{position:fixed;inset:0;z-index:2300;display:flex;align-items:center;justify-content:center;padding:16px;background:var(--journal-backdrop,#0e233abb)}.strategy-dialog{width:min(100%,1000px);max-height:calc(100dvh - 32px);display:flex;flex-direction:column;border:1px solid var(--journal-border);border-radius:15px;background:var(--journal-paper);color:var(--journal-ink);font:13px var(--journal-font);box-shadow:0 14px 55px #0005;overflow:hidden}.strategy-dialog>header{display:flex;align-items:center;gap:14px;padding:19px 23px;border-bottom:1px solid var(--journal-border);background:var(--journal-soft);flex:none}.strategy-dialog>header>div{flex:1;min-width:0}.strategy-dialog small{font-size:9px;letter-spacing:.12em;color:var(--journal-muted)}.strategy-dialog h2{font:600 25px Georgia,serif;margin:5px 0 0;color:var(--journal-heading)}.strategy-dialog>header>button{width:40px;height:40px;flex:none;border:1px solid var(--journal-border);border-radius:50%;background:var(--journal-card);color:var(--journal-ink);font-size:24px;cursor:pointer}.strategy-dialog>main{padding:22px;min-height:0;overflow:auto;overscroll-behavior:contain}@media(max-width:650px){.strategy-backdrop{padding:7px}.strategy-dialog{max-height:calc(100dvh - 14px);border-radius:12px}.strategy-dialog>header{padding:13px 15px}.strategy-dialog h2{font-size:21px}.strategy-dialog>main{padding:15px}}button:focus-visible{outline:3px solid var(--journal-accent);outline-offset:2px}</style>
